begin;

create temp table content_plan (
  id uuid primary key,
  label text not null,
  from_name_khmer text not null,
  from_name_english text not null,
  from_context text not null,
  from_description text not null,
  to_name_khmer text not null,
  to_name_english text not null,
  to_context text not null,
  to_description text not null,
  told_by text not null,
  photo_url text not null,
  created_at timestamptz not null
) on commit drop;

insert into content_plan values
  ('0164e482-97a6-405b-bdc1-28635971b617', $v$Num Ansorm Chek$v$,
   $v$នំអន្សមចេក$v$,
   $v$Num Ansorm Chek — banana sticky rice cake$v$,
   $v$Pchum Ben · Khmer New Year · Weddings$v$,
   $v$Num ansom chek is a cylinder of glutinous rice wrapped in banana leaf around a whole ripe chek nam va, the Thai banana. The Khmer dictionary of Chuon Nath defines ansom as a cake of glutinous rice wrapped in fresh leaves, usually banana, round and even at both ends, and cooked by boiling or grilling; the banana version is the first of the kinds it lists.

The tightly bound logs cook for several hours in a large pot of boiling water, the leaf keeping the water out so that the rice cooks in its own steam. The work takes time and many hands, and the same dictionary records the saying “ten people, and the ansom burns” for a crowd that still cannot get a job done.

Num ansom is closely tied to Pchum Ben. On the first days of the festival, families gather to wrap the cakes as offerings for Buddhist monks, made on behalf of departed relatives, and to share with household and friends. It is also made for Khmer New Year and for weddings. Voices quoted in the Cambodian press, among them a Ministry of Culture official, link the cylindrical ansom and its pyramid-shaped partner num kom to the Hindu god Shiva and his consort; the historian Sambo Manara describes the pair as representing mother and father.

A maker quoted in 2026 observed that families in the countryside are more likely than city families to make the cakes at home.$v$,
   $v$នំអន្សមចេក$v$,
   $v$Num Ansorm Chek — banana sticky rice cake$v$,
   $v$Festival (Pchum Ben, Khmer New Year) / Religious ceremony$v$,
   $v$A steamed cake of glutinous rice, sweet baby banana and rich coconut milk wrapped tightly in banana leaves. It is one of the most culturally significant items in Cambodian culinary heritage, woven into major ancestral and religious observances.

The outer layer of glutinous rice is soft, chewy and rich from coconut cream, balanced by the fragrant sweetness of ripe chek nam wa (baby bananas) at the core, which turn a deep reddish-purple during the long steaming.

INGREDIENTS
Glutinous rice, ripe baby bananas (chek nam wa), fresh coconut milk, sugar, salt, fresh banana leaves, split bamboo string or raffia.

PREPARATION
Glutinous rice is soaked, washed and seasoned with coconut milk, salt and sugar. Bananas are peeled and placed in the centre of rice laid flat on wilted banana leaves. The leaf is rolled tightly into a dense cylinder, tucked at both ends and bound firmly with bamboo string. The logs are boiled continuously for six to eight hours.

REGION
Nationwide — Battambang, Siem Reap and the rural agrarian heartlands.

NOTE
The cylindrical shape is a traditional symbol of unity, strength and agricultural abundance, offered to monks and ancestors.$v$,
   $v$[SOURCE PENDING — researched, not yet confirmed with family]$v$, $v$/entries/num-ansom-chek.jpg$v$, '2026-09-06T13:56:06.03886+00:00'),
  ('cd99961d-c893-4f65-ad10-4d86ad245983', $v$Num Korm$v$,
   $v$នំគម$v$,
   $v$Num Korm — palm sugar and coconut filled rice dumpling$v$,
   $v$Pchum Ben and Khmer New Year offerings · Weddings, beside num ansom · Market sweet$v$,
   $v$Num kom (នំគម, also written num korm) is a steamed cake of glutinous rice flour dough wrapped around a filling of grated coconut cooked with palm sugar; some recipes add sesame seeds. Each cake is enclosed in banana leaf and folded into a pyramid before steaming. Cambodian–English dictionaries record it as a pyramidal cake, often filled with sweetened coconut.

The name is descriptive. In the Khmer dictionary of the Supreme Patriarch Chuon Nath, kom means hunched, and the cake is defined as one shaped like a hunched back. The same entry allows a sweetened bean filling in place of coconut.

Num kom belongs to ritual as well as to the market. It is among the leaf-wrapped cakes offered to monks for Pchum Ben and Khmer New Year, and it appears at weddings beside num ansom, the cylindrical rice cake. A Cambodian historian and several Khmer writers read the pair as female and male; the reading is widely repeated, but it is an interpretation rather than a documented origin.

It is sold in Phnom Penh’s markets and by makers who supply hotels and restaurants.$v$,
   $v$នំគម$v$,
   $v$Num Korm — palm sugar and coconut filled rice dumpling$v$,
   $v$Special occasion / Weddings / Religious ceremony$v$,
   $v$A delicate, pyramid-shaped steamed dumpling of glutinous rice flour dough enclosing a sweet, aromatic filling of fresh grated coconut cooked with dark palm sugar.

The outer rice flour skin is soft and pliable against the rich, chewy interior. Toasted sesame seeds in the filling lend a warm, nutty aroma that defines traditional Khmer confectionery technique.

INGREDIENTS
Glutinous rice flour, water, Kampong Speu palm sugar (skor tnot), freshly grated coconut, toasted white sesame seeds, banana leaves cut into triangles, coconut oil or lard for brushing.

PREPARATION
Glutinous rice flour is kneaded with water into a smooth dough. The filling is cooked down by caramelising palm sugar with fresh coconut and sesame seeds. Portioned dough balls are flattened, stuffed, wrapped into precise pyramidal parcels using oiled banana leaves, and steamed for 20 to 25 minutes.

REGION
Kandal, Kampong Cham, and nationwide.

NOTE
The pyramid structure echoes the sacred stupas and architectural geometries found across ancient Khmer stone temples.$v$,
   $v$[SOURCE PENDING — researched, not yet confirmed with family]$v$, $v$/entries/num-korm.jpg$v$, '2026-09-06T13:55:06.03886+00:00'),
  ('c730fdea-fc93-44a2-ba82-4bf926ba61de', $v$Num Ansorm Chrouk$v$,
   $v$នំអន្សមជ្រូក$v$,
   $v$Num Ansorm Chrouk — savoury pork and mung bean sticky rice cake$v$,
   $v$Pchum Ben · A savoury num$v$,
   $v$Num ansom chrouk is the savoury form of num ansom: glutinous rice and mung beans wrapped in banana leaf around a core of pork and bound into a cylinder. The Khmer dictionary of Chuon Nath lists it among the kinds of ansom, defining it simply as ansom with pork at its centre, beside the banana-filled ansom chek.

It belongs in a collection of Khmer cakes and snacks by Khmer usage rather than taste. Num, the word that begins its name, is the dictionary’s term for cakes made from rice or flour, moist or dry, counted among snacks and sweets of every kind; Cambodian reporting describes num ansom as made with either savoury or sweet fillings.

Like the banana version, the logs cook for several hours in a pot of boiling water. Pork and mung bean ansom are wrapped for Pchum Ben, when cakes are offered to monks on behalf of the dead, and slices are sometimes fried.

In 2021, officials in Stung Treng described their recipe as a hallmark of the province and considered registering it as a local speciality; the same report notes that the cake is also available in other provinces.$v$,
   $v$នំអន្សមជ្រូក$v$,
   $v$Num Ansorm Chrouk — savoury pork and mung bean sticky rice cake$v$,
   $v$Festival (Pchum Ben, Khmer New Year) / Special occasion$v$,
   $v$The savoury counterpart to Num Ansorm Chek: glutinous rice layered with seasoned split yellow mung beans and a central strip of black-pepper-marinated pork belly, steamed in banana leaf cylinders.

Fat from the pork belly melts into the mung beans and rice during the long boil, giving a rich, savoury dumpling with a pungency from crushed Kampot black pepper.

INGREDIENTS
Glutinous rice, split yellow mung beans (soaked and hulled), pork belly in thick strips, black pepper, garlic, sea salt, fresh banana leaves, bamboo string.

PREPARATION
Rice is seasoned and layered over banana leaves, followed by steamed mung beans and pork belly strips marinated in pepper and salt. Wrapped into heavy cylindrical logs, bound tightly, and boiled for six to eight hours. Leftovers are sliced into thick wheels and pan-fried until golden and crisp.

REGION
Kampong Speu, Battambang, and nationwide.

NOTE
Illustrates the historic technique of preserving high-value meat cuts within a fat and rice medium for extended festival celebrations.$v$,
   $v$[SOURCE PENDING — researched, not yet confirmed with family]$v$, $v$/entries/num-ansom-chrouk.jpg$v$, '2026-09-06T13:54:06.03886+00:00'),
  ('31d7fcb7-5d07-4cff-aeee-e40444e2653b', $v$Num Plae Ai$v$,
   $v$នំផ្លែអាយ$v$,
   $v$Num Plae Ai — palm sugar sticky rice balls with fresh coconut$v$,
   $v$Everyday snack$v$,
   $v$Num plae ai (នំផ្លែអាយ) is a small sweet of glutinous rice dough wrapped around a lump of palm sugar. The Khmer dictionary of Chuon Nath describes the sugar as hidden from sight inside the dough, and gives the sweet three names: num bompuon skor, “the cake that hides the sugar”, which it calls the original and most literal; num plae ai; and, less often, num kaet kdei.

The dictionary also records explanations handed down by elders. Num plae ai, roughly “fruit of this side”, is said to go back to the reign of King Ang Duong in the nineteenth century, when the cakes were fixed in rows on branches set into a length of banana trunk, so that they looked like a fruiting tree close at hand rather than fruit picked from a tree over there.

Num kaet kdei, “the lawsuit cake”, comes from a tale of two men eating the sweets face to face. One bit a cake in half, the syrup squirted into the other’s eye, and the quarrel that followed ended before a judge. The dictionary adds that no one knows when this happened.

In recipes published today, the filled balls are boiled, cooled and rolled in grated coconut. Recipe writers describe num plae ai as an everyday snack, and one notes roadside vendors selling it in Phnom Penh.$v$,
   $v$នំផ្លែអាយ$v$,
   $v$Num Plae Ai — palm sugar sticky rice balls with fresh coconut$v$,
   $v$Daily life / Special occasion / Snack$v$,
   $v$Small, bouncy glutinous rice dumplings stuffed with a solid cube of hard palm sugar, boiled until cooked, then rolled in freshly shaved coconut.

The texture is springy and soft. Biting into a warm dumpling bursts the melted palm sugar inside, against the cool, savoury grated coconut outside.

INGREDIENTS
Glutinous rice flour, warm water, hard palm sugar cubes, freshly grated coconut, a pinch of sea salt.

PREPARATION
The dough is divided into small balls, hollowed with a thumb, stuffed with a palm sugar cube and sealed tightly. The balls are dropped into boiling water; once they float they are moved straight into cold water, then rolled in grated coconut mixed with sea salt.

REGION
Takeo, Phnom Penh, and nationwide.

NOTE
Folklore names this one num samlap pdei, the husband-killing cake — a warning never to eat one in a single warm bite, in case the hot liquid palm sugar squirts out. A street snack beloved for its short ingredient list and its play on temperature and texture.$v$,
   $v$[SOURCE PENDING — researched, not yet confirmed with family]$v$, $v$/entries/num-plae-ai.jpg$v$, '2026-09-06T13:53:06.03886+00:00'),
  ('19242196-86ef-44df-bb46-b16c7e6431e4', $v$Num Kong$v$,
   $v$នំកង$v$,
   $v$Num Kong — crispy fried rice-flour donuts with palm sugar glaze$v$,
   $v$Everyday street and market sweet$v$,
   $v$Num kong is a Cambodian fried ring cake. A dough of glutinous rice flour, sometimes with a little ordinary rice flour and, in the recipes consulted, bound with coconut milk, is rolled into ropes, looped into rings and deep-fried until golden. The rings are then coated in palm sugar cooked down to a dark caramel and scattered with sesame seeds, which gives them their glossy, honey-coloured finish.

In Khmer, kang is the everyday word for a ring or bracelet, and the cakes are ring-shaped, although no published source examined explains the name directly. In English the cake is also written num kang, noum kong and nom korng.

Published accounts describe num kong as an everyday street dessert, sold from stalls and by vendors in Phnom Penh; the sources consulted do not mention its use at festivals or ceremonies. One recent account notes the cake’s Chinese roots.$v$,
   $v$នំកង$v$,
   $v$Num Kong — crispy fried rice-flour donuts with palm sugar glaze$v$,
   $v$Daily life / Afternoon tea / Market snack$v$,
   $v$Traditional fried donuts made from rice flour and glutinous rice flour, shaped into rings, deep-fried until golden and coated with caramelised palm sugar and toasted sesame seeds.

A crunchy golden shell over a tender, chewy interior. The dark palm sugar glaze adds a deep caramel flavour lifted by the nutty aroma of white sesame.

INGREDIENTS
Rice flour, glutinous rice flour, warm water, palm sugar syrup, white sesame seeds, oil for deep frying.

PREPARATION
The flours are mixed with warm water into a pliable dough, rolled into small ropes and looped into rings. They are fried until puffed and crisp. Palm sugar is caramelised separately into a thick glaze, drizzled over the donuts and finished with toasted sesame seeds.

REGION
Siem Reap, Kampong Chhnang, and market towns.

NOTE
Reflects everyday Cambodian market culture and a deep-frying tradition built on rice rather than wheat. Sold in the late afternoon by street vendors, wrapped in fresh lotus leaf.$v$,
   $v$[SOURCE PENDING — researched, not yet confirmed with family]$v$, $v$/entries/num-korng.jpg$v$, '2026-09-06T13:52:06.03886+00:00'),
  ('10793f27-f7b5-4db0-937d-7438c573634a', $v$Num Kor$v$,
   $v$នំអាកោត្នោត$v$,
   $v$Num Akor Thnot — steamed palm-fruit rice cake$v$,
   $v$Palm-fruit season, reported May to October · Market and street sweet$v$,
   $v$Num akor thnot (នំអាកោត្នោត) is the palm-fruit form of num akor, a small steamed cake. The Khmer dictionary of Chuon Nath defines akor as a cake leavened and steamed in cups so that it rises light, and akor thnot as the version made by mixing the flesh of ripe sugar-palm fruit with flour and sugar.

The sugar palm, Borassus flabellifer, was named Cambodia’s national tree by royal decree in 2005. For this cake the fruit is left until its skin turns dark brown and orange, and the fibrous pulp is worked into a batter of rice flour, coconut cream and yeast. The light-orange batter is spooned into small cups folded from banana leaf and steamed, swelling as it cooks, and is finished with coconut cream or grated coconut.

Because it depends on ripe fruit, the cake follows the fruit season, reported as May to October, rather than the dry-season tapping of palm sap for sugar, which runs from about December to May.

Akor thnot is sold by street vendors and in markets, including at Oudong in Kampong Speu province. A 2021 report from Prey Veng describes steamed palm cakes sold at Neak Loeung market and ordered in quantity for weddings and ceremonies.$v$,
   $v$នំកោ$v$,
   $v$Num Kor — steamed palm sugar cake topped with coconut$v$,
   $v$Special occasion / Seasonal harvest / Daily life$v$,
   $v$A light, airy steamed cake of rice flour, fragrant palm fruit pulp (tnot) and palm sugar, a vibrant orange-yellow crowned with fresh salted shredded coconut.

Spongy, soft and moist, with a sweet, floral aroma that comes straight from mature palmyra palm fruit and unrefined palm sugar.

INGREDIENTS
Rice flour, mature toddy palm fruit pulp (tnot), unrefined palm sugar, coconut cream, a fermented rice starter or yeast, freshly shredded coconut, a pinch of salt.

PREPARATION
Rice flour is mixed with extracted palm fruit pulp, palm sugar and coconut cream, then left to ferment slightly for airiness. The batter is poured into small leaf cups or metal ramekins, steamed over high heat until risen and spongy, and sprinkled with salted grated coconut.

REGION
Kampong Speu and Takeo — the palm sugar producing heartlands.

NOTE
Shows the culinary use of Borassus flabellifer, the palmyra palm and Cambodia's national tree, drawing on both the fruit pulp and the tree sap. Made in the dry season, when fresh toddy palm syrup comes in from the fields.$v$,
   $v$[SOURCE PENDING — researched, not yet confirmed with family]$v$, $v$/entries/num-akor.jpg$v$, '2026-09-06T13:51:06.03886+00:00'),
  ('0edd4f19-cf3e-417d-a2c7-4aba6e9fd6b9', $v$Num Bot$v$,
   $v$នំបត់$v$,
   $v$Num Bot — folded mung bean glutinous rice dumpling$v$,
   $v$Pchum Ben offerings to monks · Weddings, beside num ansom · Market cake in Phnom Penh$v$,
   $v$Num bot (នំបត់, also romanised num bort) is a steamed cake of glutinous rice flour enclosing a mung bean filling, wrapped in banana leaf. The Modern Cambodian–English Dictionary describes the filling as salted mung beans, and a Khmer-language survey of popular cakes describes the parcels as flat. In Khmer, bot means to fold or bend, and Chuon Nath’s dictionary gives “to fold a leaf” as an example; no source consulted explains how the cake came by its name.

Num bot is closely related to num kom. The two are listed side by side among the cakes wrapped and offered to monks around Pchum Ben, and at weddings either may be set beside num ansom on the offering tray. Some popular writing treats the two names as one cake; the dictionaries list them separately.

Sources do not describe num bot as rare. In 2021 it was reported as mostly sold in markets and served at ceremonies in Phnom Penh, and in 2023 a Phnom Penh maker listed it among his wrapped cakes.$v$,
   $v$នំបត់$v$,
   $v$Num Bot — folded mung bean glutinous rice dumpling$v$,
   $v$Special occasion / Religious ceremony offerings$v$,
   $v$A folded dumpling of sweet mung bean paste enclosed in glutinous rice dough, wrapped into neat, flat rectangular banana leaf packets rather than rolled or tied.

The texture is delicate and smooth: a rich, sweet mung bean interior infused with coconut inside soft rice dough.

INGREDIENTS
Glutinous rice flour, hulled split yellow mung beans, coconut cream, white sugar, salt, softened banana leaves.

PREPARATION
Mung beans are steamed, mashed and cooked down with coconut cream and sugar until thick. Small balls of bean paste are enveloped in glutinous rice dough, placed onto flat banana leaf sheets, folded into neat flat rectangles — bot means to fold — and steamed until glossy.

REGION
Battambang and Prey Veng.

NOTE
Rare today. Where Num Korm remains widely available, Num Bot with its flat fold geometry has largely gone from urban markets and survives in select rural communities. It demonstrates a specialised banana-leaf wrapping art that depends on folding rather than string-tying.$v$,
   $v$[SOURCE PENDING — researched, not yet confirmed with family]$v$, $v$/entries/num-bot.jpg$v$, '2026-09-06T13:50:06.03886+00:00');

do $guard$
declare
  expected constant int := 7;
  found_rows int;
  changed int;
  problem text;
begin
  -- 1. Lock: no other transaction may write review history until this one
  --    ends (SHARE blocks INSERT/UPDATE/DELETE, allows reads), and none may
  --    change a target row. Then record the complete history as it stands.
  lock table public.review_history in share mode;
  perform 1 from public.entries where id in (select id from content_plan) for update;
  create temp table history_before on commit drop as select * from public.review_history;

  -- 2. Every target present, and exactly in its expected starting state.
  select count(*) into found_rows from public.entries where id in (select id from content_plan);
  if found_rows <> expected then
    raise exception 'Content rollback aborted: % of % target rows found; nothing was changed.', found_rows, expected;
  end if;
  select string_agg(p.label, ', ' order by p.label) into problem
    from content_plan p left join public.entries e on e.id = p.id
    -- "is not true" also catches a field that has become null.
    where e.id is null or (e.name_khmer = p.from_name_khmer
      and e.name_english = p.from_name_english
      and e.context = p.from_context
      and e.description = p.from_description
      and e.told_by = p.told_by and e.photo_url = p.photo_url and e.created_at = p.created_at
      and e.contributor_id is null and e.status = 'published') is not true;
  if problem is not null then
    raise exception 'Content rollback aborted: not in the expected starting state: %; nothing was changed.', problem;
  end if;

  -- 3. Change exactly these rows, still conditional on the full starting state.
  update public.entries e set
    name_khmer = p.to_name_khmer,
    name_english = p.to_name_english,
    context = p.to_context,
    description = p.to_description
    from content_plan p
    where e.id = p.id
      and e.name_khmer = p.from_name_khmer
      and e.name_english = p.from_name_english
      and e.context = p.from_context
      and e.description = p.from_description
      and e.told_by = p.told_by and e.photo_url = p.photo_url and e.created_at = p.created_at
      and e.contributor_id is null and e.status = 'published';
  get diagnostics changed = row_count;
  if changed <> expected then
    raise exception 'Content rollback aborted: % of % rows changed; nothing was changed.', changed, expected;
  end if;

  -- 4a. Identity: exactly the seven target ids are still present. An id
  --     changed underneath, or a row removed, shows up here rather than
  --     silently dropping out of the checks below.
  select count(distinct id) into found_rows from public.entries where id in (select id from content_plan);
  if found_rows <> expected then
    raise exception 'Content rollback aborted: % of % target ids present afterwards; nothing was changed.', found_rows, expected;
  end if;

  -- 4b. Every planned id, joined from the plan side so none can be skipped,
  --     holds exactly its expected result with its protected fields unchanged.
  select string_agg(p.label, ', ' order by p.label) into problem
    from content_plan p left join public.entries e on e.id = p.id
    where e.id is null or (e.name_khmer = p.to_name_khmer
      and e.name_english = p.to_name_english
      and e.context = p.to_context
      and e.description = p.to_description
      and e.told_by = p.told_by and e.photo_url = p.photo_url and e.created_at = p.created_at
      and e.contributor_id is null and e.status = 'published') is not true;
  if problem is not null then
    raise exception 'Content rollback aborted: unexpected result for: %; nothing was changed.', problem;
  end if;

  -- 4c. Review history identical in content, not just in size: every column of
  --     every row, compared as a multiset in both directions. EXCEPT ALL
  --     treats NULLs as equal and does not depend on row order, so any
  --     inserted, removed or edited row (an id, entry, status, reviewer or
  --     timestamp) is caught.
  if exists (select * from history_before except all select * from public.review_history)
     or exists (select * from public.review_history except all select * from history_before) then
    raise exception 'Content rollback aborted: review history changed; nothing was changed.';
  end if;
  raise notice 'Content rollback verified: % rows changed.', changed;
end
$guard$;

commit;

-- Report (read-only, after commit).
select id, name_khmer, name_english, left(description, 60) as opening, context
from public.entries
where id in ('0164e482-97a6-405b-bdc1-28635971b617', 'cd99961d-c893-4f65-ad10-4d86ad245983', 'c730fdea-fc93-44a2-ba82-4bf926ba61de', '31d7fcb7-5d07-4cff-aeee-e40444e2653b', '19242196-86ef-44df-bb46-b16c7e6431e4', '10793f27-f7b5-4db0-937d-7438c573634a', '0edd4f19-cf3e-417d-a2c7-4aba6e9fd6b9')
order by created_at desc;
